import Foundation

/// Complete independent float32 transform outputs from unmodified official libopus 1.6.1.
/// Generated by the opt-in CELT transform oracle verifier; encoded as little-endian IEEE754.
/// These are primitive fixtures, not compressed-packet or complete-codec conformance vectors.
enum CELTTransformOracleFixtures {
    static let values: [(Int, String, String)] = [
        (120, "", ""),
        (240, "", ""),
        (480, "", ""),
        (960, "", ""),
    ]

    /// Decodes a complete committed reference block without alignment-dependent loads.
    /// - Parameter encoded: Valid Base64 containing complete little-endian float32 words.
    /// - Returns: Frequency/time ordered float values; malformed fixtures return an empty array.
    static func decode(_ encoded: String) -> [Float] {
        guard let data = Data(base64Encoded: encoded), data.count.isMultiple(of: 4) else { return [] }
        let bytes = Array(data)
        return stride(from: 0, to: bytes.count, by: 4).map { index in
            let bits = UInt32(bytes[index]) | UInt32(bytes[index + 1]) << 8
                | UInt32(bytes[index + 2]) << 16 | UInt32(bytes[index + 3]) << 24
            return Float(bitPattern: bits)
        }
    }
}
